package defs

import (
	"path"
	"sort"
	"strings"
)

// GenerateCommand is the command that regenerates every generated file,
// named in each file's header line.
const GenerateCommand = "go run ./scripts/specshift defs generate"

// generatedHeader returns the header line of a generated file. The
// wording matches the generated-artifact rule of the scope package, which
// reads "Generated by" and "Do not edit" in a file's leading comments.
func generatedHeader(from string) string {
	return "<!-- Generated by `" + GenerateCommand + "` from " + from + ". Do not edit by hand. -->\n"
}

// table is a Markdown table with a fixed column set.
type table struct {
	header []string
	rows   [][]string
}

func (t *table) add(cells ...string) { t.rows = append(t.rows, cells) }

func (t *table) render() string {
	var sb strings.Builder
	sb.WriteString("| " + strings.Join(t.header, " | ") + " |\n")
	seps := make([]string, len(t.header))
	for i := range seps {
		seps[i] = ":--"
	}
	sb.WriteString("| " + strings.Join(seps, " | ") + " |\n")
	for _, r := range t.rows {
		cells := make([]string, len(r))
		for i, c := range r {
			cells[i] = cell(c)
		}
		sb.WriteString("| " + strings.Join(cells, " | ") + " |\n")
	}
	return sb.String()
}

// cell makes text safe for one table cell: one line, with pipes escaped.
func cell(s string) string {
	s = strings.Join(strings.Fields(s), " ")
	return strings.ReplaceAll(s, "|", `\|`)
}

// code renders a value as inline code, or as nothing when it is empty.
func code(s string) string {
	if s == "" {
		return ""
	}
	return "`" + s + "`"
}

// codes renders each value of a list as inline code.
func codes(values []string) string {
	out := make([]string, 0, len(values))
	for _, v := range values {
		out = append(out, code(v))
	}
	return strings.Join(out, ", ")
}

// relLink returns the relative path from a folder (repo-relative) to a
// repo-relative file.
func relLink(fromDir, to string) string {
	fromParts := splitPath(fromDir)
	toParts := splitPath(path.Dir(to))
	i := 0
	for i < len(fromParts) && i < len(toParts) && fromParts[i] == toParts[i] {
		i++
	}
	var parts []string
	for range fromParts[i:] {
		parts = append(parts, "..")
	}
	parts = append(parts, toParts[i:]...)
	parts = append(parts, path.Base(to))
	return strings.Join(parts, "/")
}

func splitPath(p string) []string {
	if p == "" || p == "." {
		return nil
	}
	return strings.Split(p, "/")
}

// linker renders links from one output file's folder.
type linker struct {
	fromDir string
	codes   map[string]*Page
}

// block links a block's name to the block's anchor.
func (l linker) block(b *Block) string {
	return "[`" + b.Name + "`](" + relLink(l.fromDir, b.Page.Path) + "#" + b.Anchor + ")"
}

// page links a page by its title.
func (l linker) page(p *Page) string {
	return "[" + pageTitle(p) + "](" + relLink(l.fromDir, p.Path) + ")"
}

// code links a page code to its page, or renders it plainly when no page
// registers it.
func (l linker) code(c string) string {
	if p, ok := l.codes[c]; ok {
		return "[" + c + "](" + relLink(l.fromDir, p.Path) + ")"
	}
	return c
}

// codeList links each code of a list.
func (l linker) codeList(values []string) string {
	out := make([]string, 0, len(values))
	for _, v := range values {
		out = append(out, l.code(v))
	}
	return strings.Join(out, ", ")
}

// pageTitle returns a page's level-one heading, or its file name when it
// has none.
func pageTitle(p *Page) string {
	if p.Title != "" {
		return p.Title
	}
	return strings.TrimSuffix(path.Base(p.Path), ".md")
}

// sortBlocks orders blocks by name, case-insensitively, then by anchor and
// path, so a catalog's row order is a function of the names alone.
func sortBlocks(blocks []*Block) {
	sort.SliceStable(blocks, func(i, j int) bool {
		a, b := strings.ToLower(blocks[i].Name), strings.ToLower(blocks[j].Name)
		if a != b {
			return a < b
		}
		if blocks[i].Anchor != blocks[j].Anchor {
			return blocks[i].Anchor < blocks[j].Anchor
		}
		return blocks[i].Page.Path < blocks[j].Page.Path
	})
}

// blocksOf returns the tree's blocks of the given kinds, sorted.
func blocksOf(t *Tree, kindNames ...string) []*Block {
	var out []*Block
	for _, b := range t.Blocks() {
		if contains(kindNames, b.Kind) {
			out = append(out, b)
		}
	}
	sortBlocks(out)
	return out
}

// firstSentence returns the text up to and including the first full stop
// that a space follows, or the whole text when there is none.
func firstSentence(s string) string {
	s = strings.Join(strings.Fields(s), " ")
	if i := strings.Index(s, ". "); i >= 0 {
		return s[:i+1]
	}
	return s
}
